let fuzzClosure = {

public protocol FixItMessage: Sendable {
  /// The Fix-It message that should be displayed in the client.
  var message: String { get
}

  /// See ``MessageID``.
  var fixItID: MessageID { get }
}
}

extension Fuzz {
extension RawSyntax // c
: CustomReflectable {
  @TupleProperties(RawSyntax)
  public var customMirror: Mirror {

    let mirrorChildren: [Any]
    switch view {
    case .token:
      mirrorChildren = []
    case .layout(let layoutView):
      mirrorChildren
= layoutView.children.map {
        child in child ?? (nil as Any?) as Any
      }
    }
    return Mirror(self, unlabeledChildren: mirrorChildren)
  }
}
}

protocol FuzzProtocol {
associatedtype Value
enum Nested { case value(Int) }
struct Nested { var value: Int }
var computed: Int { 1 }
@available(*, deprecated)
var annotated: Int { get async throws }
deinit { }
}

